ALTER TABLE "catalog_versions" DROP CONSTRAINT "catalog_identity";--> statement-breakpoint
ALTER TABLE "catalog_versions" DROP CONSTRAINT "catalog_body_limit";--> statement-breakpoint
ALTER TABLE "catalog_versions" DROP CONSTRAINT "catalog_real_evidence";--> statement-breakpoint
ALTER TABLE "catalog_versions" ADD CONSTRAINT "catalog_identity" CHECK ("catalog_versions"."catalog_key" ~ '^[a-z][a-z0-9-]{2,79}$' AND "catalog_versions"."version" ~ '^(0|[1-9][0-9]*)[.](0|[1-9][0-9]*)[.](0|[1-9][0-9]*)$' AND length("catalog_versions"."version") <= 40 AND "catalog_versions"."schema_version" IN ('1','2') AND "catalog_versions"."content_sha256" ~ '^[a-f0-9]{64}$');--> statement-breakpoint
ALTER TABLE "catalog_versions" ADD CONSTRAINT "catalog_body_limit" CHECK (octet_length("catalog_versions"."body"::text) between 1 and 8388608);--> statement-breakpoint
ALTER TABLE "catalog_versions" ADD CONSTRAINT "catalog_real_evidence" CHECK (coalesce("catalog_versions"."body"->'synthetic' = 'false'::jsonb AND jsonb_typeof("catalog_versions"."body"->'profiles') = 'array' AND jsonb_typeof("catalog_versions"."body"->'sources') = 'array' AND jsonb_array_length("catalog_versions"."body"->'profiles') between 1 and 300 AND jsonb_array_length("catalog_versions"."body"->'sources') between 1 and 300 AND jsonb_array_length(jsonb_path_query_array("catalog_versions"."body", '$.profiles[*] ? (@.synthetic == false)')) = jsonb_array_length("catalog_versions"."body"->'profiles') AND jsonb_array_length(jsonb_path_query_array("catalog_versions"."body", '$.sources[*] ? (@.synthetic == false)')) = jsonb_array_length("catalog_versions"."body"->'sources') AND ("catalog_versions"."schema_version" = '1' OR (jsonb_typeof("catalog_versions"."body"->'issues') = 'array' AND jsonb_array_length(jsonb_path_query_array("catalog_versions"."body", '$.issues[*] ? (@.synthetic == false)')) = jsonb_array_length("catalog_versions"."body"->'issues'))),false));